export type SoundId = 'charge' | 'clang' | 'whoosh' | 'ping' | 'boom' | 'tick';

/** Files live in web/public/sounds (generated by scripts/generate-sounds.ts) and are served from /sounds. */
export const SOUND_FILES: Readonly<Record<SoundId, { readonly src: string; readonly volume: number }>> = {
  charge: { src: '/sounds/charge.wav', volume: 0.9 },
  clang: { src: '/sounds/clang.wav', volume: 0.85 },
  whoosh: { src: '/sounds/whoosh.wav', volume: 0.8 },
  ping: { src: '/sounds/ping.wav', volume: 0.8 },
  boom: { src: '/sounds/boom.wav', volume: 1 },
  tick: { src: '/sounds/tick.wav', volume: 0.55 },
};

/** Charging Surge: playback rate climbs 12% per Charge the player already holds (capped at 2x). */
export const surgeRate = (charge: number): number => Math.min(2, 1 + 0.12 * Math.max(0, charge));

/** Ticking clock: below this many seconds left the tick starts and speeds up. */
export const TICK_BELOW_SECONDS = 10;
/** Tick tempo: the gap shrinks from ~1 s to 350 ms as the timer approaches 0, and pitch/rate rises with it. */
export const tickGapMs = (seconds: number): number => 350 + 65 * Math.max(0, Math.min(TICK_BELOW_SECONDS, seconds));
export const tickRate = (seconds: number): number => 1 + 0.06 * (TICK_BELOW_SECONDS - Math.max(0, Math.min(TICK_BELOW_SECONDS, seconds)));
